--
-- Table structure for table `code_logs`
--

DROP TABLE IF EXISTS `code_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `code_logs` (
  `log_id` int NOT NULL AUTO_INCREMENT,
  `user_pk` int NOT NULL,
  `source_code` text COMMENT '코드 길이 제한 해제',
  `is_success` tinyint(1) DEFAULT '0',
  `output_log` text,
  `execution_time` float DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `score` float DEFAULT '0' COMMENT 'ML학습용 점수',
  `ast_complexity` int DEFAULT '0' COMMENT '코드 복잡도',
  `machine_type` varchar(50) DEFAULT NULL COMMENT '로봇 종류',
  `res_common` int DEFAULT '0',
  `res_rare` int DEFAULT '0',
  `res_special` int DEFAULT '0',
  `res_exotic` int DEFAULT '0',
  `gold` int DEFAULT '0',
  `cluster_rank` int DEFAULT '-1',
  `hint_type` varchar(64) DEFAULT NULL,
  `base_score` float DEFAULT NULL,
  `personal_score` float DEFAULT NULL,
  `adoption_score` float DEFAULT NULL,
  `antipattern_pen` float DEFAULT NULL,
  `antipattern_tags` varchar(255) DEFAULT NULL,
  `reward` float DEFAULT NULL,
  `error_type` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`log_id`),
  KEY `user_pk` (`user_pk`),
  KEY `idx_created_at` (`created_at`),
  CONSTRAINT `code_logs_ibfk_1` FOREIGN KEY (`user_pk`) REFERENCES `users` (`pk_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2111 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
